                            <input type="password" class="form-control" @bind="_confirmPassword"
                                   placeholder="Confirm new password" />
                        </div>

                        <button class="btn btn-primary" @onclick="ChangePassword" disabled="@_passwordChanging">
                            @if (_passwordChanging)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                            }
                            Update Password
                        </button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="tfa-section">
                <div class="toggle-row">
                    <div class="toggle-info">
                        <span class="toggle-label">Two-Factor Authentication</span>
                        <span class="toggle-description">Add an extra layer of security to your account</span>
                    </div>
                    <div class="tfa-status-group">
                        <span class="status-badge @(_securitySettings?.TwoFactorEnabled == true ? "status-enabled" : "status-disabled")">
                            @(_securitySettings?.TwoFactorEnabled == true ? "Enabled" : "Disabled")
                        </span>
                    </div>
                </div>
            </div>

            <!-- Active Sessions -->
            <div class="sessions-section">
                <h4>Active Sessions</h4>
                @if (_securitySettings?.Sessions is { Count: > 0 })
                {
                    <div class="table-responsive">
                        <table class="table sessions-table">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th></th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var (session, index) in _securitySettings.Sessions.Select((s, i) => (s, i)))
                                {
                                    <tr>
                                        <td>
                                            <span class="device-name">@session.Device</span>
                                            @if (index == 0)
                                            {
                                                <span class="current-badge">Current</span>
                                            }
                                        </td>
                                        <td>@session.Location</td>
                                        <td>@FormatLastActive(session.LastActive)</td>
                                        <td>
                                            @if (index != 0)
                                            {
                                                <button class="btn btn-sm btn-outline-danger"
                                                        @onclick="() => RequestRevokeSession(session)">
