toolArgs.file_text:
@page "/settings"
@rendermode InteractiveServer
@using sv_44ba73016b974eaca2444af0bde0a6bd.Models
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <!-- Left Sidebar Navigation -->
    <nav class="settings-sidebar">
        <h3 class="sidebar-title">Settings</h3>
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="settings-nav-item @(ActiveSection == section.Key ? "active" : "")"
                    @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Icon</span>
                    <span class="nav-label">@section.Label</span>
                </li>
            }
        </ul>
    </nav>

    <!-- Main Content Area -->
    <div class="settings-content">
        @if (_loading)
        {
            <div class="loading-indicator">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            <!-- Toast notification -->
            @if (_showToast)
            {
                <div class="toast-message @(_toastType)">
                    <span>@_toastMessage</span>
                    <button class="toast-close" @onclick="() => _showToast = false">&times;</button>
                </div>
            }

            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }
    </div>
</div>

<!-- Session Revoke Confirmation Dialog -->
@if (_showRevokeDialog)
{
    <div class="modal-backdrop" @onclick="() => _showRevokeDialog = false"></div>
    <div class="confirmation-dialog">
        <h4>Revoke Session</h4>
        <p>Are you sure you want to revoke this session on <strong>@_sessionToRevoke?.Device</strong> from <strong>@_sessionToRevoke?.Location</strong>?</p>
        <p class="text-muted">This will sign out the device immediately.</p>
        <div class="dialog-actions">
            <button class="btn btn-secondary" @onclick="() => _showRevokeDialog = false">Cancel</button>
            <button class="btn btn-danger" @onclick="ConfirmRevokeSession" disabled="@_revoking">
                @if (_revoking)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Revoke
            </button>
        </div>
    </div>
}

@code {
    // ── Navigation ──────────────────────────────────────────────────
    private string ActiveSection { get; set; } = "profile";

    private record SectionInfo(string Key, string Label, string Icon);
    private readonly SectionInfo[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];

    // ── Toast ───────────────────────────────────────────────────────
    private bool _showToast;
    private string _toastMessage = "";
    private string _toastType = "success";
    private CancellationTokenSource? _toastCts;

    private async Task ShowToast(string message, string type = "success")
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        _toastMessage = message;
        _toastType = type;
        _showToast = true;
        StateHasChanged();

        try
        {
            await Task.Delay(4000, token);
            _showToast = false;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    // ── Loading ─────────────────────────────────────────────────────
    private bool _loading = true;

    // ── Profile State ───────────────────────────────────────────────
    private UserProfile? _savedProfile;
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";
    private bool _profileSaving;

    private bool ProfileHasChanges =>
        _savedProfile is not null &&
        (_profileDisplayName != _savedProfile.DisplayName ||
         _profileEmail != _savedProfile.Email ||
         _profileAvatarUrl != _savedProfile.AvatarUrl ||
         _profileBio != _savedProfile.Bio);

    // ── Notification State ──────────────────────────────────────────
    private bool _notifEmail;
    private bool _notifPush;
    private bool _notifDigest;
    private List<string> _allChannels = ["general", "announcements", "engineering", "design", "marketing", "support", "random"];
    private HashSet<string> _mutedChannels = new();
    private bool _notifSaving;

    // ── Security State ──────────────────────────────────────────────
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _passwordChanging;
    private bool _showRevokeDialog;
    private ActiveSession? _sessionToRevoke;
    private bool _revoking;

    // ── Appearance State ────────────────────────────────────────────
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _appearanceSaving;

    private readonly string[] _availableLanguages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Korean", "Portuguese"];

    // ── Lifecycle ───────────────────────────────────────────────────
    protected override async Task OnInitializedAsync()
    {
        try
        {
            var profileTask = SettingsService.GetProfileAsync();
            var notifTask = SettingsService.GetNotificationPrefsAsync();
            var securityTask = SettingsService.GetSecuritySettingsAsync();
            var appearanceTask = SettingsService.GetAppearanceAsync();

            await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

            var profile = profileTask.Result;
            _savedProfile = profile;
            _profileDisplayName = profile.DisplayName;
            _profileEmail = profile.Email;
            _profileAvatarUrl = profile.AvatarUrl;
            _profileBio = profile.Bio;

            var notif = notifTask.Result;
            _notifEmail = notif.EmailNotifications;
            _notifPush = notif.PushNotifications;
            _notifDigest = notif.WeeklyDigest;
            _mutedChannels = new HashSet<string>(notif.MutedChannels);

            _securitySettings = securityTask.Result;

            var appearance = appearanceTask.Result;
            _theme = appearance.Theme;
            _fontSize = appearance.FontSize;
            _language = appearance.Language;
            _compactMode = appearance.CompactMode;
        }
        catch
        {
            await ShowToast("Failed to load settings. Please try again.", "error");
        }
        finally
        {
            _loading = false;
        }
    }

    // ── Profile Actions ─────────────────────────────────────────────
    private async Task SaveProfile()
    {
        _profileSaving = true;
        try
        {
            var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
            await SettingsService.SaveProfileAsync(profile);
            _savedProfile = profile;
            await ShowToast("Profile saved successfully!");
        }
        catch
        {
            await ShowToast("Failed to save profile.", "error");
        }
        finally
        {
            _profileSaving = false;
        }
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is null) return;
        _profileDisplayName = _savedProfile.DisplayName;
        _profileEmail = _savedProfile.Email;
        _profileAvatarUrl = _savedProfile.AvatarUrl;
        _profileBio = _savedProfile.Bio;
    }

    // ── Notification Actions ────────────────────────────────────────
    private void ToggleMutedChannel(string channel, object? checkedValue)
    {
        if (checkedValue is bool muted && muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        _notifSaving = true;
        try
        {
            var prefs = new NotificationPrefs(_notifEmail, _notifPush, _notifDigest, _mutedChannels.ToList());
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            await ShowToast("Notification preferences saved!");
        }
        catch
        {
            await ShowToast("Failed to save notification preferences.", "error");
        }
        finally
        {
            _notifSaving = false;
        }
    }

    // ── Security Actions ────────────────────────────────────────────
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) ||
            string.IsNullOrWhiteSpace(_newPassword) ||
            string.IsNullOrWhiteSpace(_confirmPassword))
        {
            await ShowToast("Please fill in all password fields.", "error");
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", "error");
            return;
        }

        if (_newPassword.Length < 8)
        {
            await ShowToast("New password must be at least 8 characters.", "error");
            return;
        }

        _passwordChanging = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _changePasswordExpanded = false;
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            await ShowToast("Password updated successfully!");
        }
        catch
        {
            await ShowToast("Failed to change password. Check your current password.", "error");
        }
        finally
        {
            _passwordChanging = false;
        }
    }

    private void RequestRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeDialog = true;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;
        _revoking = true;
        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            _showRevokeDialog = false;
            _sessionToRevoke = null;
            await ShowToast("Session revoked successfully!");
        }
        catch
        {
            await ShowToast("Failed to revoke session.", "error");
        }
        finally
        {
            _revoking = false;
        }
    }

    // ── Appearance Actions ──────────────────────────────────────────
    private async Task SaveAppearance()
    {
        _appearanceSaving = true;
        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            await ShowToast("Appearance settings saved!");
        }
        catch
        {
            await ShowToast("Failed to save appearance settings.", "error");
        }
        finally
        {
            _appearanceSaving = false;
        }
    }

    // ── Render Fragments ────────────────────────────────────────────

    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile</h2>
            <p class="section-description">Manage your public profile information.</p>

            <div class="avatar-area">
                <div class="avatar-preview">
                    @if (!string.IsNullOrWhiteSpace(_profileAvatarUrl))
                    {
                        <img src="@_profileAvatarUrl" alt="Avatar" class="avatar-image" />
                    }
                    else
                    {
                        <div class="avatar-placeholder">👤</div>
                    }
                </div>
                <div class="avatar-url-display">
                    <label class="form-label">Avatar URL</label>
                    <input type="url" class="form-control" @bind="_profileAvatarUrl"
                           placeholder="https://example.com/avatar.png" />
                </div>
            </div>

            <div class="form-group">
                <label class="form-label">Display Name</label>
                <input type="text" class="form-control" @bind="_profileDisplayName"
                       placeholder="Your display name" />
            </div>

            <div class="form-group">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="_profileEmail"
                       placeholder="your@email.com" />
            </div>

            <div class="form-group">
                <label class="form-label">Bio</label>
                <textarea class="form-control" rows="4" @bind="_profileBio"
                          placeholder="Tell us about yourself..."></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveProfile"
                        disabled="@(!ProfileHasChanges || _profileSaving)">
                    @if (_profileSaving)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Save Changes
                </button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges"
                        disabled="@(!ProfileHasChanges)">
                    Discard Changes
                </button>
            </div>
        </section>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>
            <p class="section-description">Choose how and when you want to be notified.</p>

            <div class="toggle-group">
                <div class="toggle-row">
                    <div class="toggle-info">
                        <span class="toggle-label">Email Notifications</span>
                        <span class="toggle-description">Receive notifications via email</span>
                    </div>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_notifEmail" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>

                <div class="toggle-row">
                    <div class="toggle-info">
                        <span class="toggle-label">Push Notifications</span>
                        <span class="toggle-description">Receive push notifications on your devices</span>
                    </div>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_notifPush" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>

                <div class="toggle-row">
                    <div class="toggle-info">
                        <span class="toggle-label">Weekly Digest</span>
                        <span class="toggle-description">Get a weekly summary of activity</span>
