    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section class="settings-section">
            <h2>Security</h2>
            <p class="section-description">Manage your account security and active sessions.</p>

            <!-- Change Password -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <span>🔑 Change Password</span>
                    <span class="expand-icon">@(_changePasswordExpanded ? "▲" : "▼")</span>
                </button>
                @if (_changePasswordExpanded)
                {
                    <div class="panel-body">
                        @if (_securitySettings?.LastPasswordChange is not null)
                        {
                            <p class="text-muted mb-3">
                                Last changed: @_securitySettings.LastPasswordChange.Value.ToString("MMMM d, yyyy")
                            </p>
                        }

                        <div class="form-group">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword"
                                   placeholder="Enter current password" />
                        </div>

                        <div class="form-group">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword"
                                   placeholder="Enter new password (min 8 characters)" />
                        </div>

                        <div class="form-group">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword"
                                   placeholder="Confirm new password" />
                        </div>

                        <button class="btn btn-primary" @onclick="ChangePassword" disabled="@_passwordChanging">
                            @if (_passwordChanging)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                            }
                            Update Password
                        </button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="tfa-section">
                <div class="toggle-row">
                    <div class="toggle-info">
                        <span class="toggle-label">Two-Factor Authentication</span>
                        <span class="toggle-description">Add an extra layer of security to your account</span>
                    </div>
                    <div class="tfa-status-group">
                        <span class="status-badge @(_securitySettings?.TwoFactorEnabled == true ? "status-enabled" : "status-disabled")">
                            @(_securitySettings?.TwoFactorEnabled == true ? "Enabled" : "Disabled")
                        </span>
                    </div>
                </div>
            </div>

            <!-- Active Sessions -->
            <div class="sessions-section">
                <h4>Active Sessions</h4>
                @if (_securitySettings?.Sessions is { Count: > 0 })
                {
                    <div class="table-responsive">
                        <table class="table sessions-table">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th></th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var (session, index) in _securitySettings.Sessions.Select((s, i) => (s, i)))
                                {
                                    <tr>
                                        <td>
                                            <span class="device-name">@session.Device</span>
                                            @if (index == 0)
                                            {
                                                <span class="current-badge">Current</span>
                                            }
                                        </td>
                                        <td>@session.Location</td>
                                        <td>@FormatLastActive(session.LastActive)</td>
                                        <td>
                                            @if (index != 0)
                                            {
                                                <button class="btn btn-sm btn-outline-danger"
                                                        @onclick="() => RequestRevokeSession(session)">
                                                    Revoke
                                                </button>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>
                    </div>
                }
                else
                {
                    <p class="text-muted">No active sessions found.</p>
                }
            </div>
        </section>
    };

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return lastActive.ToString("MMM d, yyyy");
    }

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>
            <p class="section-description">Customize how the application looks and feels.</p>

            <!-- Theme -->
            <div class="form-group">
                <label class="form-label fw-bold">Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-option @(_theme == theme ? "selected" : "")">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <span class="radio-icon">
                                @(theme switch { "Light" => "☀️", "Dark" => "🌙", _ => "💻" })
                            </span>
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Font Size -->
            <div class="form-group">
                <label class="form-label fw-bold">Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-option @(_fontSize == size ? "selected" : "")">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <span class="size-preview" style="font-size: @(size switch { "Small" => "0.85rem", "Large" => "1.25rem", _ => "1rem" })">
                                Aa
                            </span>
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Language -->
            <div class="form-group">
                <label class="form-label fw-bold">Language</label>
                <select class="form-select" @bind="_language">
                    @foreach (var lang in _availableLanguages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="toggle-row standalone">
                <div class="toggle-info">
                    <span class="toggle-label">Compact Mode</span>
                    <span class="toggle-description">Reduce spacing and padding for a denser layout</span>
                </div>
                <label class="toggle-switch">
                    <input type="checkbox" @bind="_compactMode" />
                    <span class="toggle-slider"></span>
                </label>
            </div>

            <!-- Live Preview -->
            <div class="preview-area">
                <h4>Preview</h4>
                <div class="preview-card @GetPreviewClasses()">
                    <div class="preview-header">
                        <span class="preview-dot"></span>
                        <span class="preview-dot"></span>
                        <span class="preview-dot"></span>
                        <span class="preview-title">Sample Card</span>
                    </div>
                    <div class="preview-body" style="font-size: @GetPreviewFontSize()">
                        <p class="preview-text">This is how your content will look with the selected settings.</p>
                        <div class="preview-meta">
                            <span>Language: @_language</span>
                            <span>•</span>
                            <span>Compact: @(_compactMode ? "On" : "Off")</span>
                        </div>
                        <div class="preview-button-row">
                            <span class="preview-btn primary">Primary</span>
                            <span class="preview-btn secondary">Secondary</span>
                        </div>
                    </div>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_appearanceSaving">
                    @if (_appearanceSaving)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Save
                </button>
            </div>
        </section>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_theme switch { "Dark" => "preview-dark", "Light" => "preview-light", _ => "preview-system" });
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private string GetPreviewFontSize() => _fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };
}

